CREATE FUNCTION public.respond_invitation(p_id uuid,p_status text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE inv public.invitations; t public.teams; ev public.events; BEGIN IF auth.uid() IS NULL OR p_status NOT IN ('accepted','declined') THEN RAISE EXCEPTION 'Invalid request'; END IF; SELECT * INTO inv FROM public.invitations WHERE id=p_id FOR UPDATE; IF NOT FOUND OR inv.recipient_id<>auth.uid() OR inv.status<>'pending' THEN RAISE EXCEPTION 'Request unavailable'; END IF; SELECT * INTO t FROM public.teams WHERE id=inv.team_id FOR UPDATE; IF t.leader_id<>auth.uid() OR NOT t.is_open THEN RAISE EXCEPTION 'Team leader access required'; END IF; SELECT * INTO ev FROM public.events WHERE id=t.event_id; IF p_status='accepted' THEN IF (SELECT count(*) FROM public.team_members WHERE team_id=t.id)+1>=ev.team_max THEN RAISE EXCEPTION 'Team is full'; END IF; INSERT INTO public.team_members(team_id,user_id,display_name) SELECT t.id,inv.sender_id,display_name FROM public.profiles WHERE id=inv.sender_id ON CONFLICT DO NOTHING; END IF; UPDATE public.invitations SET status=p_status WHERE id=p_id; INSERT INTO public.notifications(user_id,title,body) VALUES(inv.sender_id,'Team request '||p_status,t.name||' — your request was '||p_status||'.'); RETURN true; END $$;
REVOKE ALL ON FUNCTION public.respond_invitation(uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.respond_invitation(uuid,text) TO authenticated;
CREATE FUNCTION public.validate_event_update() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.capacity<(SELECT count(*) FROM public.passes WHERE event_id=NEW.id AND NOT cancelled) THEN RAISE EXCEPTION 'Capacity cannot be lower than existing attendees'; END IF; IF NEW.team_min<1 OR NEW.team_max>10 THEN RAISE EXCEPTION 'Invalid team size'; END IF; IF NEW.deadline>NEW.starts_at THEN RAISE EXCEPTION 'Registration deadline must precede the event'; END IF; IF jsonb_typeof(NEW.questions)<>'array' OR jsonb_array_length(NEW.questions)>20 THEN RAISE EXCEPTION 'Invalid event questions'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_event BEFORE INSERT OR UPDATE ON public.events FOR EACH ROW EXECUTE FUNCTION public.validate_event_update();
CREATE FUNCTION public.validate_registration_answers() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE q jsonb; BEGIN IF jsonb_typeof(NEW.answers)<>'object' OR octet_length(NEW.answers::text)>40000 THEN RAISE EXCEPTION 'Invalid answers'; END IF; FOR q IN SELECT jsonb_array_elements(questions) FROM public.events WHERE id=NEW.event_id LOOP IF jsonb_typeof(q)='string' AND length(trim(coalesce(NEW.answers->>(q#>>'{}'),'')))=0 THEN RAISE EXCEPTION 'Answer every event question'; END IF; END LOOP; RETURN NEW; END $$;
CREATE TRIGGER validate_answers BEFORE INSERT ON public.registrations FOR EACH ROW EXECUTE FUNCTION public.validate_registration_answers();
CREATE FUNCTION public.validate_profile() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE s text; BEGIN IF cardinality(NEW.skills)>20 OR cardinality(NEW.interests)>20 THEN RAISE EXCEPTION 'Choose up to 20 skills and interests'; END IF; FOREACH s IN ARRAY (NEW.skills||NEW.interests) LOOP IF length(s) NOT BETWEEN 1 AND 40 THEN RAISE EXCEPTION 'Invalid skill or interest'; END IF; END LOOP; RETURN NEW; END $$;
CREATE TRIGGER validate_profile BEFORE INSERT OR UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.validate_profile();